import{_ as c,C as d,o,c as u,a2 as i,b as r,w as e,a as n,E as s,a3 as l}from"./chunks/framework.CgxQ0r6v.js";const h=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md"};function p(f,a,g,b,I,A){const t=d("Mermaid");return o(),u("div",null,[a[2]||(a[2]=i('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV)&quot;">​</a></h2><h3 id="eje-tematico-alcance-del-pst-ii-abordaje-comunitario-y-diagnostico-participativo" tabindex="-1">Eje Temático: Alcance del PST II, Abordaje Comunitario y Diagnóstico Participativo <a class="header-anchor" href="#eje-tematico-alcance-del-pst-ii-abordaje-comunitario-y-diagnostico-participativo" aria-label="Permalink to &quot;Eje Temático: Alcance del PST II, Abordaje Comunitario y Diagnóstico Participativo&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-evolucion-de-la-informatica-en-el-trayecto-ii" tabindex="-1">🧭 Introducción: La Evolución de la Informática en el Trayecto II <a class="header-anchor" href="#🧭-introduccion-la-evolucion-de-la-informatica-en-el-trayecto-ii" aria-label="Permalink to &quot;🧭 Introducción: La Evolución de la Informática en el Trayecto II&quot;">​</a></h2><p>En el Trayecto I del Programa Nacional de Formación en Informática (PNFI), el estudiante adquiere una visión diagnóstica y operativa centrada en el soporte técnico a usuarios, mantenimiento preventivo/correctivo de computadores y alfabetización tecnológica en comunidades.</p><p>Al ingresar al <strong>Trayecto II</strong>, el horizonte profesional y sociotecnológico evoluciona de manera sustancial:</p><ol><li><strong>Del Mantenimiento al Desarrollo:</strong> El estudiante ya no solo repara o mantiene infraestructura existente; ahora se convierte en un <strong>analista y desarrollador de software y soluciones informáticas</strong>.</li><li><strong>De la Asistencia a la Transformación Organizacional:</strong> Los problemas comunitarios no se limitan a &quot;computadoras lentas&quot;, sino a desorganización de procesos, pérdida de información, lentitud en la atención a usuarios y falta de trazabilidad en datos críticos de consejos comunales, ambulatorios, escuelas y cooperativas.</li><li><strong>El Software como Bien Público:</strong> Bajo la filosofía del PNFI y las directrices de la UPTT &quot;Mario Briceño Iragorry&quot;, las soluciones deben concebirse bajo estándares de <strong>Soberanía Tecnológica</strong>, fomentando el uso de plataformas y herramientas libres para garantizar la independencia técnica de las comunidades.</li></ol>',8)),(o(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-36",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%22%F0%9F%9B%A0%EF%B8%8F%20Trayecto%20I%3A%20Soporte%20y%20Mantenimiento%22%5D%20--%3E%7CEvoluci%C3%B3n%20Curricular%7C%20B%5B%22%F0%9F%92%BB%20Trayecto%20II%3A%20Desarrollo%20de%20Software%20e%20Informaci%C3%B3n%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%93%8B%20Diagn%C3%B3stico%20Participativo%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22%F0%9F%93%8A%20Levantamiento%20de%20Requerimientos%22%5D%0A%20%20%20%20B%20--%3E%20E%5B%22%F0%9F%9A%80%20Construcci%C3%B3n%20de%20Sistemas%20Operativos%2FWeb%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20B%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20C%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20E%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<hr><h2 id="🏛️-capitulo-i-el-alcance-del-pst-ii-segun-el-documento-rector-del-pnfi" tabindex="-1">🏛️ CAPÍTULO I: El Alcance del PST II según el Documento Rector del PNFI <a class="header-anchor" href="#🏛️-capitulo-i-el-alcance-del-pst-ii-segun-el-documento-rector-del-pnfi" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Alcance del PST II según el Documento Rector del PNFI&quot;">​</a></h2><p>El Documento Rector del PNFI establece con claridad el perfil y las competencias asociadas al Trayecto II:</p><blockquote><p><strong>Competencia General del Trayecto II:</strong> Desarrollar aplicaciones informáticas (de escritorio, web o cliente-servidor) que gestionen información y resuelvan problemáticas reales en comunidades, organizaciones sociales e instituciones del sector público o socioproductivo, aplicando principios de ingeniería de requerimientos, diseño estructurado/orientado a objetos y bases de datos relacionales.</p></blockquote><h3 id="_1-1-lineas-de-investigacion-aplicadas-en-el-pst-ii" tabindex="-1">1.1 Líneas de Investigación Aplicadas en el PST II <a class="header-anchor" href="#_1-1-lineas-de-investigacion-aplicadas-en-el-pst-ii" aria-label="Permalink to &quot;1.1 Líneas de Investigación Aplicadas en el PST II&quot;">​</a></h3><p>En consonancia con las Líneas Institucionales de Investigación de la UPTT, los proyectos del PST II deben inscribirse principalmente en:</p><table tabindex="0"><thead><tr><th>Línea de Investigación</th><th>Área de Aplicación en PST II</th><th>Ejemplos de Proyectos Típicos</th></tr></thead><tbody><tr><td><strong>Línea 1: Desarrollo de Software Libre</strong></td><td>Aplicaciones administrativas, académicas y de servicios comunitarios.</td><td>Sistema de gestión de inventario para dispensario médico comunitario; Sistema de control de beneficios CLAP para consejo comunal.</td></tr><tr><td><strong>Línea 2: Redes y Telecomunicaciones</strong></td><td>Conectividad y servicios web locales.</td><td>Despliegue de un portal de consulta ciudadana o intranet local en escuelas rurales.</td></tr><tr><td><strong>Línea 3: Seguridad Informática y Auditoría</strong></td><td>Respaldo, integridad y privacidad de datos comunitarios.</td><td>Implementación de esquemas de autenticación y políticas de copias de seguridad de expedientes civiles.</td></tr></tbody></table><hr><h2 id="🧩-capitulo-ii-el-abordaje-comunitario" tabindex="-1">🧩 CAPÍTULO II: El Abordaje Comunitario <a class="header-anchor" href="#🧩-capitulo-ii-el-abordaje-comunitario" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Abordaje Comunitario&quot;">​</a></h2><p>El abordaje comunitario no es una simple visita protocolar; es un proceso científico, social y metodológico mediante el cual el equipo desarrollador se inserta respetuosamente en la comunidad para generar confianza y compromiso mutuo.</p><h3 id="_2-1-pasos-del-protocolo-de-insercion-comunitaria" tabindex="-1">2.1 Pasos del Protocolo de Inserción Comunitaria <a class="header-anchor" href="#_2-1-pasos-del-protocolo-de-insercion-comunitaria" aria-label="Permalink to &quot;2.1 Pasos del Protocolo de Inserción Comunitaria&quot;">​</a></h3><ol><li><strong>Identificación de la Comunidad u Organización:</strong> Localización geográfica, caracterización demográfica y tipo de organización (consejo comunal, junta de vecinos, institución pública, ambulatorio, empresa de propiedad social).</li><li><strong>Contacto Formal e Institucional:</strong> Emisión de la carta de presentación institucional expedida por el Departamento de Informática / Coordinación de Proyectos de la UPTT.</li><li><strong>Identificación de Actores Clave (Stakeholders):</strong> Identificar a los líderes comunitarios (voceros de mesas técnicas, directores, secretarios, coordinadores) y a los usuarios operativos que conviven diariamente con el problema.</li><li><strong>Acuerdo de Trabajo y Cronograma de Encuentros:</strong> Establecer días, horarios y dinámicas de reunión que no interfieran con las labores cotidianas de la comunidad.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>El Principio de Simetría del Conocimiento:</strong> Los estudiantes aportan el conocimiento técnico informático; los miembros de la comunidad aportan el conocimiento empírico de su realidad y sus necesidades. Ninguno es superior al otro. Un proyecto fracasa cuando el desarrollador cree saber lo que la comunidad necesita sin haberla escuchado.</p></div><hr><h2 id="🔍-capitulo-iii-el-diagnostico-participativo-en-el-desarrollo-de-software" tabindex="-1">🔍 CAPÍTULO III: El Diagnóstico Participativo en el Desarrollo de Software <a class="header-anchor" href="#🔍-capitulo-iii-el-diagnostico-participativo-en-el-desarrollo-de-software" aria-label="Permalink to &quot;🔍 CAPÍTULO III: El Diagnóstico Participativo en el Desarrollo de Software&quot;">​</a></h2><p>El <strong>Diagnóstico Participativo</strong> es el proceso sistemático donde la comunidad y los desarrolladores identifican, clasifican y priorizan colectivamente las situaciones problemáticas susceptibles de solución tecnológica.</p>',16)),(o(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-149",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20D1%5B%221.%20Determinar%20la%20Situaci%C3%B3n%20Problem%C3%A1tica%22%5D%20--%3E%20D2%5B%222.%20Elaborar%20el%20Plan%20Diagn%C3%B3stico%22%5D%0A%20%20%20%20D2%20--%3E%20D3%5B%223.%20Recopilar%20la%20Informaci%C3%B3n%20(Instrumentos)%22%5D%0A%20%20%20%20D3%20--%3E%20D4%5B%224.%20Procesar%20y%20Sistematizar%20los%20Datos%22%5D%0A%20%20%20%20D4%20--%3E%20D5%5B%225.%20Socializar%20los%20Resultados%20en%20Asamblea%22%5D%0A%20%20%20%20D5%20--%3E%7CAprobaci%C3%B3n%20Comunitaria%7C%20D6%5B%22Firma%20de%20Acta%20y%20Validaci%C3%B3n%20de%20Alcance%22%5D%0A%0A%20%20%20%20style%20D1%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20D2%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20D3%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20D4%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20D5%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20D6%20fill%3A%2315803d%2Cstroke%3A%2322c55e%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h3 id="_3-1-las-5-fases-del-diagnostico-participativo" tabindex="-1">3.1 Las 5 Fases del Diagnóstico Participativo <a class="header-anchor" href="#_3-1-las-5-fases-del-diagnostico-participativo" aria-label="Permalink to &quot;3.1 Las 5 Fases del Diagnóstico Participativo&quot;">​</a></h3><ol><li><strong>Determinar el problema preliminar:</strong> Reconocer indicios de ineficiencia (archivos físicos extraviados, colas excesivas de atención, falta de reportes estadísticos).</li><li><strong>Elaborar el Plan Diagnóstico:</strong> Especificar qué información se necesita, quiénes la tienen, qué técnicas se aplicarán y en qué fechas.</li><li><strong>Recopilar la información:</strong> Aplicación en campo de entrevistas estructuradas, encuestas, minutas de observación y revisión de libros de actas o formatos en papel.</li><li><strong>Procesar la información:</strong> Clasificar las necesidades identificadas, cuantificar el impacto y separar problemas puramente de infraestructura física de problemas de gestión de datos y software.</li><li><strong>Socializar los resultados:</strong> Presentar ante la asamblea comunitaria o directiva el diagnóstico consolidado para que ellos mismos validen si las prioridades reflejadas corresponden a su realidad.</li></ol><hr><h2 id="📊-capitulo-iv-analisis-de-involucrados-stakeholders" tabindex="-1">📊 CAPÍTULO IV: Análisis de Involucrados (Stakeholders) <a class="header-anchor" href="#📊-capitulo-iv-analisis-de-involucrados-stakeholders" aria-label="Permalink to &quot;📊 CAPÍTULO IV: Análisis de Involucrados (Stakeholders)&quot;">​</a></h2><p>En todo proyecto informático existen grupos e individuos con intereses directos o indirectos. El <strong>Análisis de Involucrados</strong> permite mapear sus expectativas, poder de decisión y nivel de afectación.</p><h3 id="matriz-de-involucrados-plantilla-oficial" tabindex="-1">Matriz de Involucrados (Plantilla Oficial) <a class="header-anchor" href="#matriz-de-involucrados-plantilla-oficial" aria-label="Permalink to &quot;Matriz de Involucrados (Plantilla Oficial)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Grupo / Actor</th><th>Intereses / Expectativas</th><th>Problemas Percibidos</th><th>Recursos y Mandatos</th><th>Posición frente al Proyecto (Aliado/Neutro/Opositor)</th></tr></thead><tbody><tr><td><strong>Vocero Principal / Director</strong></td><td>Obtener reportes confiables para toma de decisiones y rendición de cuentas.</td><td>Falta de control sobre los registros que manejan los operadores.</td><td>Firma institucional, autoridad para aprobar el sistema.</td><td><strong>Aliado Estratégico</strong></td></tr><tr><td><strong>Operador / Secretaria</strong></td><td>Reducir el tiempo de registro y evitar duplicación de trabajo manual.</td><td>Temor a que el sistema sea muy complejo o miedo a perder su puesto de trabajo.</td><td>Manejo diario de la información, conocimiento exacto de las excepciones y reglas de negocio.</td><td><strong>Inicialmente Cauteloso / Potencial Aliado</strong></td></tr><tr><td><strong>Comunidad / Beneficiario Final</strong></td><td>Recibir constancias, trámites o citas de manera ágil sin demoras.</td><td>Pérdida de expedientes, tiempos de espera excesivos de varios días.</td><td>Demanda de servicios públicos de calidad.</td><td><strong>Beneficiario Directo</strong></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Gestión del Cambio Organizacional:</strong> Uno de los mayores riesgos en PST II es la resistencia al cambio por parte de los operadores acostumbrados al papel. Involucrarlos desde el diagnóstico haciéndoles sentir co-diseñadores del software garantiza una tasa de éxito e implantación cercana al 100%.</p></div><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para superar exitosamente la Evaluación 1 del Trimestre IV, cada equipo debe presentar:</p><ol><li><strong>Carta de Aceptación Institucional / Comunitaria:</strong> Sellada y firmada por la máxima autoridad comunitaria.</li><li><strong>Plan Diagnóstico Documentado:</strong> Objetivos, técnicas aplicadas e instrumentos de recolección.</li><li><strong>Matriz de Involucrados Consolidada:</strong> Mapeo de actores y expectativas.</li><li><strong>Acta de Socialización del Diagnóstico:</strong> Con firmas de asistencia de los miembros de la comunidad que validaron la necesidad de desarrollar la solución informática.</li></ol>',12))])}const y=c(m,[["render",p]]);export{h as __pageData,y as default};
